def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]

    # The colored tracks are parallel lines. Find which line orientation
    # groups the most cells together.
    key_funcs = [
        lambda r, c: r,
        lambda r, c: c,
        lambda r, c: c - r,
        lambda r, c: r + c,
    ]
    groups_by_orientation = []
    for fn in key_funcs:
        groups = {}
        for r, c, color in points:
            groups.setdefault(fn(r, c), []).append(color)
        groups_by_orientation.append(groups)

    orientation = max(
        range(len(key_funcs)),
        key=lambda i: max((len(v) for v in groups_by_orientation[i].values()), default=0)
    )
    groups = groups_by_orientation[orientation]
    period = len(groups)

    # Each track specifies the color for its position modulo the period.
    residue_color = {}
    for key, colors in groups.items():
        counts = {}
        for color in colors:
            counts[color] = counts.get(color, 0) + 1
        residue_color[key % period] = max(counts, key=counts.get)

    fn = key_funcs[orientation]
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            row.append(residue_color[fn(r, c) % period])
        out.append(row)
    return out
